<?php require_once 'funciones.php'; exigir_login();if(($_SESSION['rol']??'')!=='cliente'){header('Location: admin/index.php');exit;}$uid=(int)$_SESSION['usuario_id'];$q=$conn->prepare('SELECT p.*,mp.nombre pago,me.nombre envio FROM pedidos p JOIN metodos_pago mp ON mp.id=p.metodo_pago_id JOIN metodos_envio me ON me.id=p.metodo_envio_id WHERE p.usuario_id=? ORDER BY p.creado_en DESC');$q->bind_param('i',$uid);$q->execute();$rs=$q->get_result();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mis pedidos</title><link rel="stylesheet" href="estilos.css"></head><body><div class="barra">COMO EN CASA <span><a href="tienda.php">Menú</a> · <a href="cerrar_sesion.php">Salir</a></span></div><main class="contenedor"><h1 class="titulo">Mis pedidos</h1><div class="panel tabla-wrap"><table><tr><th>N.º</th><th>Fecha</th><th>Total</th><th>Envío</th><th>Pago</th><th>Estado</th></tr><?php while($p=$rs->fetch_assoc()):?><tr><td>#<?=$p['id']?></td><td><?=e($p['creado_en'])?></td><td>S/ <?=number_format($p['total'],2)?></td><td><?=e($p['envio'])?></td><td><?=e($p['pago'])?></td><td><span class="etiqueta"><?=e($p['estado'])?></span></td></tr><?php endwhile;?></table></div></main></body></html>
